#!/usr/bin/env bash
# Fetches real IEC 61131-3 Structured Text from public repositories (their
# own library sources and test suites), checks each file's SHA-256, and runs
# crates/helmsman-iec/tests/st_corpus.rs against them: per file, whether it
# parses and whether it compiles, a total, and the refusals ranked by cause.
# WengerAG/structured-text-utilities and tkucic/UniTest are MIT; the test
# directories of ruSTy (LGPL-3.0), matiec (GPL-3.0), iec-checker (LGPL-3.0)
# and blark (GPL-2.0) are fetched into target/ rather than committed.
# Provenance is in docs/SOURCES.md. The files are data only: nothing from
# them is executed.
#
# Needs: curl, shasum (or sha256sum), xargs, cargo, network on the first run.
# Idempotent: files already present with the right hash are not fetched.
# Corpus location: $HELMSMAN_ST_CORPUS (default target/st-corpus).
set -euo pipefail
cd "$(dirname "$0")/.."

corpus="${HELMSMAN_ST_CORPUS:-$PWD/target/st-corpus}"

# Corpus name -> raw-file base URL at a pinned commit.
url_of() {
  case "$1" in
    wenger) echo "https://raw.githubusercontent.com/WengerAG/structured-text-utilities/5afc27c7f879e2d1fcd727003aab2a9b34174e40" ;;
    unitest) echo "https://raw.githubusercontent.com/tkucic/UniTest/7d8bbb1752acd975e944f1219deff2541835ed3a" ;;
    # tests/lit/single/**/*.st
    rusty) echo "https://raw.githubusercontent.com/PLC-lang/rusty/11e8107e96749c3d68cc36377af5e32c9abea2b8" ;;
    # tests/**/*.st
    matiec) echo "https://raw.githubusercontent.com/beremiz/matiec/c316fe57e335381cbe91f61c7366857198580ac7" ;;
    # test/st/**/*.st (user2.st is empty and left out)
    iec-checker) echo "https://raw.githubusercontent.com/jubnzv/iec-checker/d3e5dae2c9b5096a197e4134d7d0549201f3a953" ;;
    # blark/tests/source/*.st
    blark) echo "https://raw.githubusercontent.com/klauer/blark/78349296737ae0cdf6485b202e0a8e4ddea79999" ;;
    *)
      echo "unknown corpus $1" >&2
      exit 1
      ;;
  esac
}

sha256() {
  if command -v sha256sum >/dev/null; then sha256sum "$1"; else shasum -a 256 "$1"; fi | cut -d' ' -f1
}

# Internal: fetch one file and check its hash (run by xargs below).
if [ "${1:-}" = "--fetch" ]; then
  name="$2" want="$3" path="$4"
  dest="$corpus/$name/$path"
  mkdir -p "$(dirname "$dest")"
  curl -fsSL --retry 3 -o "$dest.part" "$(url_of "$name")/$path"
  got="$(sha256 "$dest.part")"
  if [ "$got" != "$want" ]; then
    rm -f "$dest.part"
    echo "SHA-256 mismatch for $name/$path: got $got, want $want" >&2
    exit 1
  fi
  mv "$dest.part" "$dest"
  exit 0
fi

