todo="$(mktemp)"
trap 'rm -f "$todo"' EXIT
total=0
fetched=0
while read -r name want path; do
  [ -n "$name" ] || continue
  total=$((total + 1))
  dest="$corpus/$name/$path"
  if [ -f "$dest" ] && [ "$(sha256 "$dest")" = "$want" ]; then
    continue
  fi
  printf '%s\0%s\0%s\0' "$name" "$want" "$path" >>"$todo"
  fetched=$((fetched + 1))
done <<<"$manifest"

if [ -s "$todo" ]; then
  xargs -0 -n 3 -P 8 "$0" --fetch <"$todo"
fi
echo "corpus: $corpus ($total files, $fetched fetched)"

HELMSMAN_ST_CORPUS="$corpus" cargo test --locked -p helmsman-iec --test st_corpus -- --nocapture
